public class LinkedList {
    private Node head;

    class Node {
        int value;
        Node next;
        Node(int v) { value = v; }
    }

    public void add(int value) {
        Node n = new Node(value);
        if (head == null) {
            head = n;
        } else {
            Node curr = head
            while (curr.next != null) {
                curr = curr.next;
            }
            curr.next = n;
        }
    }
}

